// Enclosure for Hasp Biometric Smart Lock
// Outer: 135 x 90 x 48 mm, Wall: 2 mm

$fn = 40;
wall = 2.0;
w = 135; d = 90; h = 48;
r = 4;

module rounded_box(x, y, z, rad) {
    hull() {
        translate([-x/2 + rad, -y/2 + rad, 0]) cylinder(r=rad, h=z);
        translate([ x/2 - rad, -y/2 + rad, 0]) cylinder(r=rad, h=z);
        translate([-x/2 + rad,  y/2 - rad, 0]) cylinder(r=rad, h=z);
        translate([ x/2 - rad,  y/2 - rad, 0]) cylinder(r=rad, h=z);
    }
}

module hasp_base() {
    difference() {
        rounded_box(w, d, h - 8, r);
        translate([0, 0, wall])
            rounded_box(w - 2*wall, d - 2*wall, h, r - 1);

        // Servo deadbolt latch extension slot on right face
        translate([w/2 - 1, 20, 10])
            cube([wall + 2, 16, 20]);

        // DC Power Jack
        translate([-w/2 - 1, 14, 6])
            cube([wall + 2, 10, 11]);
    }
}

module hasp_lid() {
    translate([0, 0, h + 10]) {
        difference() {
            rounded_box(w, d, 8, r);
            // Angled Fingerprint scanner optical window cutout
            translate([35, -18, -1])
                cube([22, 16, 12], center=true);
            // 5mm LED Bezel cutouts
            translate([10, -28, -1]) cylinder(r=2.6, h=12);
            translate([-4, -28, -1]) cylinder(r=2.6, h=12);
        }
    }
}

hasp_base();
hasp_lid();

code.ino:
/*
 * Solder Showcase: Hasp — Biometric Fingerprint Smart Lock
 * Target: Arduino Uno (ATmega328P)
 * Pins:
 *   D2: Fingerprint TX (SoftwareSerial RX)
 *   D3: Fingerprint RX (SoftwareSerial TX)
 *   D9: SG90 Servo PWM Signal
 *   D5: Active Piezo Buzzer
 *   D11: Green LED (Unlock)
 *   D12: Red LED (Denied)
 */

#include <SoftwareSerial.h>
#include <Servo.h>

SoftwareSerial fingerSerial(2, 3);
Servo deadboltServo;

const int PIN_BUZZER = 5;
const int PIN_LED_GREEN = 11;
const int PIN_LED_RED = 12;

const int SERVO_LOCKED_POS = 0;
const int SERVO_UNLOCKED_POS = 90;
const unsigned long AUTO_LOCK_DELAY_MS = 5000;

bool isUnlocked = false;
unsigned long unlockTimestamp = 0;

void setup() {
  Serial.begin(9600);
  fingerSerial.begin(57600);

  pinMode(PIN_BUZZER, OUTPUT);
  pinMode(PIN_LED_GREEN, OUTPUT);
  pinMode(PIN_LED_RED, OUTPUT);

  deadboltServo.attach(9);
  deadboltServo.write(SERVO_LOCKED_POS);

  digitalWrite(PIN_LED_RED, HIGH);
  delay(300);
  digitalWrite(PIN_LED_RED, LOW);

  Serial.println(F("SCANNER_READY"));
}

void unlockLatch() {
  Serial.println(F("ACCESS_GRANTED"));
  deadboltServo.write(SERVO_UNLOCKED_POS);
  digitalWrite(PIN_LED_GREEN, HIGH);
  digitalWrite(PIN_LED_RED, LOW);
  isUnlocked = true;
  unlockTimestamp = millis();

  // Success double chirp
  digitalWrite(PIN_BUZZER, HIGH);
  delay(80);
  digitalWrite(PIN_BUZZER, LOW);
  delay(60);
  digitalWrite(PIN_BUZZER, HIGH);
  delay(80);
  digitalWrite(PIN_BUZZER, LOW);

  Serial.println(F("SERVO_UNLOCKED"));
}

void lockLatch() {
  deadboltServo.write(SERVO_LOCKED_POS);
  digitalWrite(PIN_LED_GREEN, LOW);
  digitalWrite(PIN_LED_RED, LOW);
  isUnlocked = false;
  Serial.println(F("SERVO_LOCKED"));
}

void denyAccess() {
  Serial.println(F("ACCESS_DENIED"));
  digitalWrite(PIN_LED_RED, HIGH);
  digitalWrite(PIN_BUZZER, HIGH);
  delay(400);
  digitalWrite(PIN_BUZZER, LOW);
  digitalWrite(PIN_LED_RED, LOW);
}

void loop() {
  if (isUnlocked && (millis() - unlockTimestamp >= AUTO_LOCK_DELAY_MS)) {
    lockLatch();
  }

  if (Serial.available()) {
    char cmd = Serial.read();
    if (cmd == 'U' || cmd == '1') {
      unlockLatch();
    } else if (cmd == 'D' || cmd == '0') {
      denyAccess();
    }
  }

  delay(100);
}
